  List<SessionRecord> path,
  StructuredViewState state,
) => [
  for (final record in path)
    if (!state.isCovered(record.id) &&
        record is! HiddenRangeRecord &&
        !state.hiddenRecordIds.contains(record.id) &&
        projectsStructured(record))
