+ToolResultMessage _result(String callId, String name, String text) =>
+    ToolResultMessage(
+      toolCallId: callId,
+      toolName: name,
+      content: [TextContent(text: text)],
+      isError: false,
+      timestamp: DateTime.utc(2026),
