      if (priorFold != null) {
        // Issue #729 chunked fold: the running summary of the chunks
        // summarized so far rides the same folded-checkpoint envelope the
        // depth-cap flattening uses.
        prompt
          ..writeln('<folded-checkpoint>')
          ..writeln(priorFold)
          ..writeln('</folded-checkpoint>');
