    final budget = summarizerWindow == null
        ? null
        : summarizationPayloadBudget(summarizerWindow!, settings);
    var prompt = build(serializeConversation(messages), openAsks, null);
    if (budget != null && estimateStringTokens(prompt) > budget) {
