      for (final record in rangeRecords)
        if (record.message.role == 'user') record.message: record.id,
    };
    List<String> asksFor(List<Message> chunk) => userRequestCandidateLines(
      [
        for (final m in chunk)
          if (askIdOf.containsKey(m)) m,
