          ..writeln('<folded-checkpoint>')
          // Issue #1131: older persisted checkpoints re-enter this prompt
          // verbatim — heal them so poison cannot be paraphrased forward.
          ..writeln(sanitizeSummary(folded.text).text)
          ..writeln('</folded-checkpoint>');
