      final text = _flattenUser(user.content);
      final synthetic = isSyntheticUserText(text);
      return LedgerEntry._(
        seq: seq,
        recordId: record.id,
        record: record,
        kind: synthetic ? 'notice' : 'user',
        tokens: estimateTokens(message),
        preview: _clip(text),
        toolNames: '',
      );
    default:
      return null;
  }
}

