String hiddenMarker({
  required int seq,
  required String kind,
  required int tokens,
  String? preview,
  bool pinned = false,
}) {
  final pin = pinned ? '·pinned' : '';
  final tail = preview == null || preview.isEmpty ? '' : '·"$preview"';
  return '[$seq:hidden·$kind·${formatMarkerTokens(tokens)}$pin$tail]';
}

/// The marker header for a compact checkpoint:
