      if (state.hiddenRecordIds.contains(record.id)) return const [];
      return emitted.add(record.id)
          ? [_checkpointMessage(record, byId: byId, seqs: seqs, state: state)]
          : const [];
    case MessageRecord():
      return [
        _messageAt(
          record,
          state: state,
          seqs: seqs,
          hiddenCallIds: hiddenCallIds,
        ),
      ];
