        kind: 'ckpt',
        tokens: estimateTokens(UserMessage.text(ckpt.text)),
        preview: _clip(ckpt.text),
        toolNames: '',
      );
    case CompactionRecord legacy:
      return LedgerEntry._(
        seq: seq,
        recordId: record.id,
        record: record,
        kind: 'legacy-ckpt',
