      // window — summarize chunk-wise and thread each chunk's summary into
      // the next, so the request that finally lands is bounded even when
      // the whole checkpoint range is not.
      return _chunkedFold(
        messages,
        build: build,
        asksFor: asksFor,
        budget: budget,
      );
    }
