Future<void> _onAgentEvent(AgentEvent event, CancelToken cancelToken) async {
  // A new user turn opens a fresh budget (Q6: per-TURN).
  if (event is MessageStartEvent && event.message is UserMessage) {
    _spentTokens = 0;
