+      calls: [
+        ToolCall(
+          id: 'ex$callNumber',
+          name: compactExpandToolName,
+          arguments: {'target': target},
+        ),
+      ],
+    ),
+  );
+  await session.appendMessage(
+    _result('ex$callNumber', compactExpandToolName, answer),
+  );
+  return answer;
+}
