String formatMarkerTokens(int tokens) {
  if (tokens < 1000) return '$tokens';
  if (tokens < 10000) {
    final k = (tokens / 1000).toStringAsFixed(1);
    return '${k.endsWith('.0') ? k.substring(0, k.length - 2) : k}k';
