    startSeq: startSeq,
    endSeq: endSeq,
    coveredTokens: coveredTokens,
    textTokens: estimateTokens(UserMessage.text(text)),
    coversRanges: idsToRanges(covers),
  );
  final index = hiddenIndexSection([
