/// Compacts sorted numeric ids into range notation: `3,5,7-8,12`.
String idsToRanges(Iterable<int> ids) {
  final sorted = [...ids]..sort();
  final parts = <String>[];
  var start = -1;
  var prev = -1;
  void flush() {
    if (start < 0) return;
    parts.add(start == prev ? '$start' : '$start-$prev');
    start = -1;
  }

  for (final value in sorted) {
    if (start >= 0 && value == prev + 1) {
      prev = value;
