        fallback: switch (pass.kind) {
          'checkpoint' => 'structured·ckpt',
          'hide-fallback' => 'structured·hide-fallback',
          _ => 'structured·hide',
        },
        ok: pass.ok,
        error: pass.error,
        hiddenRecords: pass.hiddenCount,
        summarizedMessages: pass.summarizedCount,
        summary: pass.summary,
      ),
    );
  }
}

