      case r'\':
        buffer.write(r'\\');
      case "'":
        buffer.write(r"\'");
      case r'$':
        buffer.write(r'\$');
      case '\n':
        buffer.write(r'\n');
      case '\r':
        buffer.write(r'\r');
      case '\t':
        buffer.write(r'\t');

